(function(E){ const x = E["int-m1"] = E["int-m1"] || {units:{}}; x.units["int-1"] = {"grammar":{"id":"c-int-1-g","level":"B1","course":"interview","unit":"int-1","title":"Your career: present perfect or past simple","titleTr":"Kariyerin: present perfect mi, past simple mı","titleFa":"سابقه‌ی کاری‌ات: حال کامل یا گذشته‌ی ساده","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Finished time: past simple","In 2022 I joined the bank."],["Up to now, for / since: have + past participle","I have worked there since 2022."],["Experience, no time: have + past participle","I have never missed a deadline."],["Question","How long have you been a nurse?"]]},"wrong":"I work at this bank since 2022.","right":"I have worked at this bank since 2022.","blank":{"sentence":"In 2018 she ___ her first job as a software tester.","word":"started","distractors":["has started","starts"]},"wrong2":"I have finished my degree in 2021.","right2":"I finished my degree in 2021.","blank2":{"sentence":"I ___ in customer service since 2021.","word":"have worked","distractors":["work","worked"]},"expParts":{"rule":[{"en":"A finished time (in 2019, last year): past simple.","tr":"Bitmiş bir zaman (in 2019, last year): past simple.","fa":"برای زمان تمام‌شده (مثل in 2019 یا last year) گذشته‌ی ساده می‌آوری.","ex":"In 2022 I joined the bank."},{"en":"Counting up to now (for, since): have + past participle.","tr":"Bugüne kadar saymak (for, since): have + üçüncü hâl.","fa":"برای کاری که تا الان ادامه دارد (با for یا since)، have و اسم مفعول می‌آوری.","ex":"I have worked in sales for eight years."},{"en":"No time given (never, so far): have + past participle.","tr":"Zamansız deneyim (never, ever, so far): have + üçüncü hâl.","fa":"برای تجربه‌ای بدون زمان مشخص هم have و اسم مفعول می‌آوری، مثلاً با never یا so far.","ex":"I have never missed a deadline."},{"en":"for + a length of time; since + a starting point.","tr":"for + süre; since + başlangıç noktası.","fa":"برای مدت زمان for می‌آید و برای نقطه‌ی شروع since.","ex":"for eight years / since 2016"}],"test":{"en":"Is there a finished time (in 2019, ago, last year)? Past simple. Counting up to now? have + past participle.","tr":"Bitmiş bir zaman var mı (in 2019, ago, last year)? Past simple. Bugüne kadar mı sayıyorsun? have + üçüncü hâl.","fa":"زمان تمام‌شده‌ای در جمله هست (in 2019، ago، last year)؟ پس گذشته‌ی ساده بیاور. تا امروز را حساب می‌کنی؟ پس have و اسم مفعول بیاور."},"contrast":{"en":"Turkish and Persian use a present verb here, so 'I work here since 2022' feels right. English needs have worked.","tr":"Türkçe 'sekiz yıldır çalışıyorum' der; fiil şimdiki zamandadır. Bu yüzden 'I work here since 2022' doğru gelir. İngilizcede burada have worked gerekir.","fa":"در فارسی می‌گوییم «هشت سال است کار می‌کنم» و فعل حال است؛ برای همین «I work here since 2022» درست به نظر می‌رسد. انگلیسی اینجا have worked می‌خواهد."}},"errorWatch":[{"find":["i work here since","i work there since","i am working here since","i am working there since","i work at this bank since","i work as a nurse since","i work in sales since","since eight years","since five years","since two years","since three years","since ten years"],"fix":{"en":"Counting up to now? Use have + past participle: 'I have worked here since 2022.' for + a length of time, since + a starting point.","tr":"Bugüne kadar mı sayıyorsun? have + üçüncü hâl kullan: 'I have worked here since 2022.' for + süre, since + başlangıç noktası.","fa":"اگر تا امروز را حساب می‌کنی، have و اسم مفعول می‌آوری: «I have worked here since 2022.‎» برای مدت زمان for می‌آید و برای نقطه‌ی شروع since."}},{"find":["have joined the bank in","have finished my degree in","have graduated in","have moved to istanbul in","have came","have went"],"fix":{"en":"A finished time takes the past simple: 'In 2022 I joined the bank.'","tr":"Bitmiş bir zaman past simple ister: 'In 2022 I joined the bank.'","fa":"زمان تمام‌شده گذشته‌ی ساده می‌خواهد: «In 2022 I joined the bank.‎»"}}]},"b2":{"id":"c-int-1-b2","level":"B2","track":"B2","course":"interview","unit":"int-1","title":"Recent work: present perfect continuous","titleTr":"Son dönemdeki işin: present perfect continuous","titleFa":"کار این مدت: حال کامل استمراری","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Still going on","I have been training new staff since May."],["Result or number","I have trained four people so far."],["Question","What have you been working on recently?"],["Stative verb: no -ing","I have known my manager for six years."]]},"wrong":"Since May I train two new colleagues.","right":"Since May I have been training two new colleagues.","blank":{"sentence":"Lately I ___ on a new rota for the night shift.","word":"have been working","distractors":["am working since","work"]},"wrong2":"I have been knowing my manager for six years.","right2":"I have known my manager for six years.","blank2":{"sentence":"So far I ___ four new colleagues, and all of them passed.","word":"have trained","distractors":["have been training","am training"]},"useIn":{"en":"B2: in your introduction, add one recent activity with have been + -ing (for example 'For the last year I have been...').","tr":"B2: tanıtımına have been + -ing ile yakın zamanda yaptığın bir etkinlik ekle (örneğin 'For the last year I have been...').","fa":"در مسیر B2: در معرفی‌ات یک کار تازه را با have been و فعل با ing بگو (مثلاً «For the last year I have been...»)."},"exitItem":{"from":"int-1","kind":"blank","prompt":"For the last two months she ___ for her interviews every evening.","options":["has been preparing","prepares","is preparing since"],"correct":0},"expParts":{"tryFrom":"blank","rule":[{"en":"Started before, still going on: have been + -ing.","tr":"Önce başladı, hâlâ sürüyor: have been + -ing.","fa":"وقتی کاری قبلاً شروع شده و هنوز ادامه دارد، have been و فعل با ing می‌آوری.","ex":"I have been training new staff since May."},{"en":"A result or a number: have + past participle.","tr":"Bir sonuç ya da sayı: have + üçüncü hâl.","fa":"برای نتیجه یا عدد، have و اسم مفعول می‌آوری.","ex":"I have trained four people so far."},{"en":"know, like, own: no -ing.","tr":"know, like, own: -ing almaz.","fa":"فعل‌های know، like و own شکل ing نمی‌گیرند.","ex":"I have known my manager for six years."}],"test":{"en":"Can you add 'and I'm still doing it'? Use have been + -ing. Can you count it? Use have + past participle.","tr":"Sonuna 've hâlâ yapıyorum' ekleyebiliyor musun? have been + -ing kullan. Sayabiliyor musun? have + üçüncü hâl kullan.","fa":"می‌توانی به آخر جمله «و هنوز دارم انجامش می‌دهم» اضافه کنی؟ پس have been و فعل با ing بیاور. می‌توانی آن را بشماری؟ پس have و اسم مفعول بیاور."},"contrast":{"en":"Turkish 'altı aydır eğitiyorum' and Persian 'شش ماه است دارم آموزش می‌دهم' use a present verb, so learners say 'I train since May'. English needs have been training.","tr":"Türkçe 'altı aydır eğitiyorum' der; fiil şimdiki zamandadır. Bu yüzden 'I train since May' denir. İngilizcede have been training gerekir.","fa":"در فارسی می‌گوییم «شش ماه است دارم آموزش می‌دهم» و فعل حال است؛ برای همین خیلی از ما می‌گوییم «I train since May». انگلیسی have been training می‌خواهد."}},"errorWatch":[{"find":["have been knowing","am knowing","been owning"],"fix":{"en":"know and own do not take -ing: 'I have known my manager for six years.'","tr":"know ve own -ing almaz: 'I have known my manager for six years.'","fa":"فعل‌های know و own شکل ‎-ing نمی‌گیرند: «I have known my manager for six years.‎»"}},{"find":["since may i train","i train since","i am training since","i am working on it since","i am preparing since"],"fix":{"en":"Still going on since a point in the past? Use have been + -ing: 'I have been training them since May.'","tr":"Geçmişteki bir noktadan beri hâlâ sürüyor mu? have been + -ing kullan: 'I have been training them since May.'","fa":"از نقطه‌ای در گذشته شروع شده و هنوز ادامه دارد؟ پس have been و فعل با ing بیاور: «I have been training them since May.‎»"}}]},"vocab":{"id":"c-int-1-v","level":"B1","category":"vocab","course":"interview","unit":"int-1","goals":["career"],"title":{"en":"Your 60 Seconds","tr":"Senin 60 Saniyen","fa":"۶۰ ثانیه‌ی تو"},"cards":[{"word":"background","sentence":"My background is in accounting.","meaning":{"en":"Your past work and studies.","tr":"(mesleki) geçmiş, altyapı.","fa":"سابقه؛ پیشینه‌ی کاری و تحصیلی"}},{"word":"experience","sentence":"She has six years of experience in hotel reception.","meaning":{"en":"Knowledge and skill you get from doing a job.","tr":"deneyim, tecrübe.","fa":"تجربه؛ سابقه‌ی کار"}},{"word":"currently","sentence":"I currently work for a small software company.","meaning":{"en":"Now, at the present time.","tr":"şu anda, hâlihazırda.","fa":"در حال حاضر"}},{"word":"be responsible for","sentence":"I am responsible for the monthly reports.","meaning":{"en":"To have the job of doing or looking after something.","tr":"-den sorumlu olmak.","fa":"مسئولِ ... بودن"},"gap":"responsible for","accept":["responsible for"]},{"word":"skill","sentence":"Dealing with difficult customers is my strongest skill.","meaning":{"en":"Something you can do well because you learned or practised it.","tr":"beceri.","fa":"مهارت"}},{"word":"apply for","sentence":"I am applying for the team leader position.","meaning":{"en":"To ask officially for a job, usually in writing.","tr":"(bir işe) başvurmak.","fa":"برای (کاری) درخواست دادن"},"gap":"applying for","accept":["applying for"]},{"word":"position","sentence":"The position is based in Ankara and starts in April.","meaning":{"en":"A job in a company.","tr":"pozisyon, kadro.","fa":"سمت؛ موقعیت شغلی"}},{"word":"requirement","sentence":"The main requirement in this ad is three years of sales experience.","meaning":{"en":"Something an employer says you must have.","tr":"şart, aranan nitelik","fa":"شرط، چیزی که کارفرما لازم دارد"}},{"word":"reliable","sentence":"My manager says I am the most reliable person on the team.","meaning":{"en":"Someone you can trust to do what they promise.","tr":"güvenilir.","fa":"قابل‌اعتماد"}},{"word":"a good fit","sentence":"I think I would be a good fit for this role.","meaning":{"en":"The right person for a job and a team.","tr":"işe ve ekibe uygun kişi.","fa":"آدمِ مناسبِ یک کار و یک تیم"}}]},"judge":{"id":"c-int-1-j","course":"interview","unit":"int-1","type":"judge","title":{"en":"Now, before, why","tr":"Şimdi, önce, neden","fa":"الان، قبلاً، چرا"},"prompt":"Five answers to \"Tell me about yourself\", from five different people.","parts":["Now","Before, matching the job","Why this job"],"instruction":{"en":"Tap what each answer has. The strongest answer has all three.","tr":"Her cevapta ne olduğuna dokun. En güçlü cevapta üçü de vardır.","fa":"روی چیزهایی که هر جواب دارد بزن. قوی‌ترین جواب هر سه را دارد."},"items":[{"by":"Graduate","answer":"I was born in a small town, and I was always good at school. My parents wanted me to study engineering, so I did.","present":[],"fix":{"en":"A life story, and nothing here helps the interviewer. Start with now: \"I recently graduated in civil engineering.\"","tr":"Bu bir hayat hikâyesi ve mülakatçının işine yarayan bir şey yok. Şimdiyle başla: \"I recently graduated in civil engineering.\"","fa":"این داستان زندگی است و هیچ‌چیزش به کار مصاحبه‌کننده نمی‌آید. با الان شروع کن: «I recently graduated in civil engineering.»"}},{"by":"AI tool","answer":"I am a passionate, results-driven professional with a proven track record of exceeding expectations.","present":[],"fix":{"en":"Anyone could say this, and it has no fact in it. Replace it with your job, one number and one reason.","tr":"Bunu herkes söyleyebilir ve içinde tek bir gerçek yok. Yerine işini, bir sayıyı ve bir nedeni koy.","fa":"این را هر کسی می‌تواند بگوید و هیچ واقعیتی در آن نیست. به‌جایش شغلت، یک عدد و یک دلیل را بگذار."}},{"by":"Nurse","answer":"I currently work as a nurse in a children's hospital. I have looked after up to ten patients a shift for six years.","present":["Now","Before, matching the job"],"fix":{"en":"Clear, but it stops too early. Add the why: \"I'm applying because I want to train new nurses.\"","tr":"Net, ama çok erken bitiyor. Nedeni ekle: \"I'm applying because I want to train new nurses.\"","fa":"روشن است، ولی زود تمام می‌شود. بگو چرا این کار را می‌خواهی: «I'm applying because I want to train new nurses.»"}},{"by":"Sales assistant","answer":"I want this job because my manager is difficult and the pay is low.","present":[],"fix":{"en":"This says why you want to leave, not why you want this job. Say what you want next, and leave your manager out.","tr":"Bu, neden ayrılmak istediğini söylüyor; bu işi neden istediğini değil. Bundan sonra ne istediğini söyle, yöneticini işin içine katma.","fa":"این می‌گوید چرا می‌خواهی بروی، نه چرا این کار را می‌خواهی. بگو بعد از این چه می‌خواهی و پای مدیرت را وسط نکش."}},{"by":"Good model","answer":"I currently work as a software tester at an online bank. I have tested its payment app for three years and found more than 400 bugs before release. I'm applying because your team builds health apps, and I want my testing to help patients.","present":["Now","Before, matching the job","Why this job"],"fix":null}]},"speaking":{"id":"int-1","course":"interview","unit":"int-1","topic":{"en":"Your 60-second introduction","tr":"60 saniyelik tanıtımın","fa":"معرفی ۶۰ ثانیه‌ای تو"},"questions":[{"en":"Now: say what you do today, in one or two sentences.","tr":"Şimdi: bugün ne yaptığını bir iki cümleyle söyle.","fa":"الان: در یکی دو جمله بگو امروز چه کار می‌کنی."},{"en":"Before: say one or two things you have done that matter for this job. Use have + past participle and one year.","tr":"Önce: bu iş için önemli olan, yaptığın bir iki şeyi söyle. have + üçüncü hâl ve bir yıl kullan.","fa":"قبلاً: یکی دو کاری را بگو که کرده‌ای و برای این شغل مهم‌اند. فعل را با have و اسم مفعول بگو و یک سال مشخص هم بیاور."},{"en":"Why: say why you want this job, not only why you want to leave your old one.","tr":"Neden: sadece eski işinden neden ayrılmak istediğini değil, bu işi neden istediğini söyle.","fa":"چرا: بگو چرا این کار را می‌خواهی، نه فقط اینکه چرا می‌خواهی کار قبلی‌ات را ترک کنی."},{"en":"Put the three parts together and answer: \"So, tell me about yourself.\"","tr":"Üç parçayı birleştir ve cevap ver: \"So, tell me about yourself.\"","fa":"سه بخش را کنار هم بگذار و جواب بده: «So, tell me about yourself.‎»"}],"followups":[{"en":"Same three parts, fewer words: 90 seconds, then 60, then 45.","tr":"Aynı üç parça, daha az kelime: 90 saniye, sonra 60, sonra 45.","fa":"همان سه بخش را با کلمه‌های کمتر بگو: اول در ۹۰ ثانیه، بعد ۶۰ و بعد ۴۵."}],"expressions":[{"phrase":"I currently work as...","meaning":{"en":"Opens the \"now\" part.","tr":"\"Şimdi\" kısmını başlatır.","fa":"بخش «الان» را شروع می‌کند."}},{"phrase":"I have ... for ... years.","meaning":{"en":"Counts your experience up to now.","tr":"Bugüne kadarki deneyimini anlatır.","fa":"تجربه‌ات را تا امروز حساب می‌کند."}},{"phrase":"I'm applying because...","meaning":{"en":"Opens the \"why\" part.","tr":"\"Neden\" kısmını başlatır.","fa":"بخش «چرا» را شروع می‌کند."}}],"selfCheck":[{"en":"I started with now: what I do today.","tr":"Şimdiyle başladım: bugün ne yaptığımla.","fa":"با الان شروع کردم: کاری که امروز می‌کنم."},{"en":"I gave one thing I have done, with a number (years, people or a result).","tr":"Yaptığım bir şeyi bir sayıyla verdim (yıl, kişi ya da sonuç).","fa":"یکی از کارهایی را که کرده‌ام با یک عدد گفتم (سال، تعداد آدم یا یک نتیجه)."},{"en":"I said why I want this job, not only why I want to leave.","tr":"Sadece neden ayrılmak istediğimi değil, bu işi neden istediğimi söyledim.","fa":"گفتم چرا این کار را می‌خواهم، نه فقط اینکه چرا می‌خواهم بروم."},{"en":"Round 3 fitted in 45 seconds, and I did not start with my school days.","tr":"3. tur 45 saniyeye sığdı ve okul yıllarımla başlamadım.","fa":"دور سوم در ۴۵ ثانیه جا شد و با دوران مدرسه‌ام شروع نکردم."}],"warmup":{"en":"Open a job ad you like. Write three words on paper: one for now, one for before, one for why. No ad yet? Use this one: Customer Support Specialist at an online travel company (two or more years with customers, good written English, weekend shifts; it now sells trips in six new countries).","tr":"Beğendiğin bir iş ilanını aç. Kâğıda üç kelime yaz: biri şimdi, biri önce, biri neden için. Henüz ilanın yok mu? Bunu kullan: Çevrimiçi bir seyahat şirketinde Customer Support Specialist (müşterilerle en az iki yıl deneyim, iyi yazılı İngilizce, hafta sonu vardiyaları; şirket artık altı yeni ülkede seyahat satıyor).","fa":"یک آگهی شغلی را که دوست داری باز کن. سه کلمه روی کاغذ بنویس: یکی برای الان، یکی برای قبلاً، یکی برای چرا. هنوز آگهی نداری؟ از این استفاده کن: Customer Support Specialist در یک شرکت سفر اینترنتی (دست‌کم دو سال کار با مشتری، انگلیسی نوشتاری خوب، شیفت آخر هفته؛ این شرکت حالا در شش کشور تازه سفر می‌فروشد)."},"model":"I currently work as a receptionist at a hotel in Antalya, where I check in about sixty guests a day. I have worked with international guests for five years, and last year I started training new staff too. I'm applying because your company runs a customer support team for travellers, and I want to solve bigger problems for people."},"writing":{"id":"c-int-1-w","course":"interview","unit":"int-1","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your 60-second answer","tr":"60 saniyelik cevabın","fa":"جواب ۶۰ ثانیه‌ای تو"},"portfolio":"int-final-1","prompt":{"en":"Choose a job ad you like and underline its three main requirements. Write your own answer to \"Tell me about yourself\" for that job (70-100 words): now, before (one or two things that match the ad, with numbers) and why this job. Write it to be said, not read: short sentences. No ad yet? Use this one: Customer Support Specialist at an online travel company (two or more years with customers, good written English, weekend shifts; it now sells trips in six new countries). No job yet? Use your studies, a part-time job or volunteer work.","tr":"Beğendiğin bir iş ilanı seç ve üç temel şartının altını çiz. O iş için \"Tell me about yourself\" sorusuna kendi cevabını yaz (70-100 kelime): şimdi, önce (ilana uyan, içinde sayı olan bir iki şey) ve neden bu iş. Okumak için değil, söylemek için yaz: kısa cümleler. Henüz ilanın yok mu? Bunu kullan: Çevrimiçi bir seyahat şirketinde Customer Support Specialist (müşterilerle en az iki yıl deneyim, iyi yazılı İngilizce, hafta sonu vardiyaları; şirket artık altı yeni ülkede seyahat satıyor). Henüz işin yok mu? Okulunu, yarı zamanlı bir işini ya da gönüllü çalışmanı kullan.","fa":"یک آگهی شغلی که دوست داری انتخاب کن و زیر سه شرط اصلی‌اش خط بکش. برای همان کار جواب خودت را به «Tell me about yourself» بنویس (۷۰ تا ۱۰۰ کلمه): الان، قبلاً (یکی دو کار مرتبط با آگهی، با عدد) و چرا این کار. طوری بنویس که بشود آن را گفت، نه خواند؛ پس جمله‌ها کوتاه باشند. هنوز آگهی نداری؟ از این استفاده کن: Customer Support Specialist در یک شرکت سفر اینترنتی (دست‌کم دو سال کار با مشتری، انگلیسی نوشتاری خوب، شیفت آخر هفته؛ این شرکت حالا در شش کشور تازه سفر می‌فروشد). هنوز کار نکرده‌ای؟ از تحصیل، کار پاره‌وقت یا کار داوطلبانه‌ات استفاده کن."},"model":"I currently work as an accountant at a furniture company in Bursa. I prepare the monthly reports and manage payments to about forty suppliers. I joined the company in 2019. Since then, I have cut the time for our month-end close from eight days to five. I have also trained two junior colleagues. I'm applying because your finance team works with clients abroad, and I want to use my English and my reporting skills every day.","frame":"I currently work as ___ at ___. I ___ . I joined ___ in ___. Since then, I have ___. I'm applying because ___.","words":[{"word":"currently"},{"word":"joined"},{"word":"have cut"},{"word":"applying"}],"minWords":70,"minSentences":5,"rubric":["Task done: now, before and why this job are all there","Organised: now first, then the past that matters, then why","Language: past simple with a finished time; have + past participle with for, since or never","Tone: confident and simple, no list of adjectives about yourself"],"rubricI18n":{"tr":["Görev: şimdi, önce ve neden bu iş, üçü de var","Düzen: önce şimdi, sonra işle ilgili geçmiş, sonra neden","Dil: bitmiş zamanla past simple; for, since ya da never ile have + üçüncü hâl","Üslup: kendinden emin ve sade; kendin hakkında sıfat listesi yok"],"fa":["کامل بودن کار: الان، قبلاً و چرا این کار، هر سه آمده‌اند","نظم: اول الان، بعد گذشته‌ای که به این کار مربوط است، بعد چرا","زبان: گذشته‌ی ساده با زمان تمام‌شده؛ have و اسم مفعول با for، since یا never","لحن: مطمئن و ساده، بدون فهرستی از صفت‌ها درباره‌ی خودت"]}},"exit":{"id":"c-int-1-x","course":"interview","unit":"int-1","type":"exit","items":[{"from":"int-1","kind":"blank","prompt":"She ___ her accounting degree in 2019.","options":["has finished","finished","finishes"],"correct":1,"point":2},{"from":"int-1","kind":"blank","prompt":"Our new colleague ___ in sales since March.","options":["has worked","works","worked"],"correct":0,"point":2},{"from":"int-1","kind":"mcq","prompt":"What should you do before you write your introduction?","options":["Learn your whole CV by heart, word for word","Underline the main requirements in the job ad","Write down your life story from your school days"],"correct":1,"point":1},{"from":"int-1","kind":"mcq","prompt":"Which is the best way to start \"Tell me about yourself\"?","options":["I was born in 1996 in a small town near the coast.","I currently work as a nurse in a children's clinic.","I am honest, friendly and hard-working, and people like me."],"correct":1,"point":1},{"from":"int-1","kind":"mcq","prompt":"In \"Tell me about yourself\", the \"why\" part should say...","options":["why you want this job","why you left school","why your manager is difficult"],"correct":0,"point":1},{"from":"int-1","kind":"blank","prompt":"He ___ manages a team of four at a bank in Tabriz.","options":["currently","lately","recently"],"correct":0,"point":2}]},"explain":{"id":"c-int-1-e","course":"interview","unit":"int-1","type":"explain","level":"B1","title":{"en":"Tell me about yourself","tr":"Bana kendinden bahset","fa":"از خودت بگو"},"objective":{"en":"After this lesson, you can introduce yourself in 60 to 90 seconds for one specific job.","tr":"Bu dersin sonunda belirli bir iş için kendini 60-90 saniyede tanıtabileceksin.","fa":"بعد از این درس می‌توانی خودت را برای یک کار مشخص در ۶۰ تا ۹۰ ثانیه معرفی کنی."},"hook":{"en":"\"Tell me about yourself\" really asks: why are you right for this job? So give three short parts: what you do now, what you have done that matches the job, and why you want it.","tr":"\"Tell me about yourself\" aslında şunu sorar: Bu iş için neden uygunsun? Bu yüzden üç kısa parça söyle: şimdi ne yaptığın, daha önce yaptıklarından işe uyanlar ve bu işi neden istediğin.","fa":"سؤال «Tell me about yourself» در واقع می‌پرسد چرا برای این کار مناسبی. پس سه بخش کوتاه بگو: الان چه کار می‌کنی، چه کارهایی کرده‌ای که به این شغل ربط دارد و چرا این کار را می‌خواهی."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Answer in three parts: now, before, why","tr":"Üç parçada cevapla: şimdi, önce, neden","fa":"در سه بخش جواب بده: الان، قبلاً، چرا"},"steps":[{"en":"First underline the job ad's top three needs. They decide what you say.","tr":"Önce iş ilanında en çok istenen üç şeyin altını çiz. Ne söyleyeceğini bunlar belirler.","fa":"اول زیر سه چیزی که آگهی شغلی بیشتر از همه می‌خواهد خط بکش. این‌ها تعیین می‌کنند چه بگویی.","ex":"Customer support, English, shift work"},{"en":"Now: say what you do today in one sentence, so they know who you are.","tr":"Şimdi: Bugün ne yaptığını tek cümleyle söyle; böylece kim olduğunu hemen anlarlar.","fa":"در بخش «الان» در یک جمله بگو امروز چه کار می‌کنی تا زود بفهمند چه کسی هستی.","ex":"I currently work as a receptionist in Antalya."},{"en":"Before: give two facts that match the ad. Numbers make them believable.","tr":"Önce: İlana uyan iki gerçeği söyle. Sayılar onları inandırıcı yapar.","fa":"در بخش «قبلاً» دو واقعیت مرتبط با آگهی را بگو، چون عددها حرفت را باورپذیر می‌کنند.","ex":"I have helped about 60 guests a day for five years."},{"en":"Why: say why you want this job. Talk of leaving sounds negative.","tr":"Neden: Bu işi neden istediğini söyle. Ayrılmaktan söz etmek olumsuz duyulur.","fa":"در بخش «چرا» بگو چرا این کار را می‌خواهی. از ترک کارت حرف نزن، چون منفی به نظر می‌رسد.","ex":"I want to solve bigger problems for customers."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Your career: present perfect or past simple","tr":"Kariyerin: present perfect mi, past simple mı","fa":"سابقه‌ی کاری‌ات: حال کامل یا گذشته‌ی ساده"},"steps":[{"en":"A finished time (in 2019, last year): past simple.","tr":"Bitmiş bir zaman (in 2019, last year): past simple.","fa":"برای زمان تمام‌شده (مثل in 2019 یا last year) گذشته‌ی ساده می‌آوری.","ex":"In 2022 I joined the bank."},{"en":"Counting up to now (for, since): have + past participle.","tr":"Bugüne kadar saymak (for, since): have + üçüncü hâl.","fa":"برای کاری که تا الان ادامه دارد (با for یا since)، have و اسم مفعول می‌آوری.","ex":"I have worked in sales for eight years."},{"en":"No time given (never, so far): have + past participle.","tr":"Zamansız deneyim (never, ever, so far): have + üçüncü hâl.","fa":"برای تجربه‌ای بدون زمان مشخص هم have و اسم مفعول می‌آوری، مثلاً با never یا so far.","ex":"I have never missed a deadline."},{"en":"for + a length of time; since + a starting point.","tr":"for + süre; since + başlangıç noktası.","fa":"برای مدت زمان for می‌آید و برای نقطه‌ی شروع since.","ex":"for eight years / since 2016"}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Finished time: past simple","In 2022 I joined the bank."],["Up to now, for / since: have + past participle","I have worked there since 2022."],["Experience, no time: have + past participle","I have never missed a deadline."],["Question","How long have you been a nurse?"]]},"tip":{"en":"Turkish and Persian use a present verb here, so 'I work here since 2022' feels right. English needs have worked.","tr":"Türkçe 'sekiz yıldır çalışıyorum' der; fiil şimdiki zamandadır. Bu yüzden 'I work here since 2022' doğru gelir. İngilizcede burada have worked gerekir.","fa":"در فارسی می‌گوییم «هشت سال است کار می‌کنم» و فعل حال است؛ برای همین «I work here since 2022» درست به نظر می‌رسد. انگلیسی اینجا have worked می‌خواهد."},"wrong":"I have worked at Vestel from 2019 to 2022.","right":"I worked at Vestel from 2019 to 2022."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Say it, don't recite it","tr":"Söyle, ezberden okuma","fa":"بگو، از حفظ نخوان"},"body":{"en":"Don't memorise every word. It sounds like reading, and you get lost if interrupted. Keep three words in mind: now, before, why. They often ask next about what you mention, so mention only what you can discuss. Just graduated? Your \"now\" is your degree or final project.","tr":"Her kelimeyi ezberleme. Ezberlenmiş cevap yapay duyulur ve biri sözünü kesince dağılır. Aklında üç anahtar kelime tut: şimdi, önce, neden. Sonraki soru çoğu zaman söylediklerinden çıkar; bu yüzden yalnızca konuşabileceğin şeylerden bahset. Yeni mezunsan \"şimdi\", diploman ya da bitirme projendir.","fa":"هر کلمه را حفظ نکن. جواب حفظ‌شده خشک به نظر می‌رسد و اگر کسی وسط حرفت بپرد، رشته‌ی کلام از دستت می‌رود. سه کلمه‌ی کلیدی در ذهنت نگه دار: الان، قبلاً، چرا. سؤال بعدی اغلب از حرف‌های خودت درمی‌آید، پس فقط چیزی را بگو که می‌توانی درباره‌اش حرف بزنی. اگر تازه فارغ‌التحصیل شده‌ای، «الان» یعنی مدرک یا پروژه‌ی پایانی‌ات."},"phrases":[{"phrase":"I currently work as...","meaning":{"en":"Opens the \"now\" part.","tr":"\"Şimdi\" kısmını başlatır.","fa":"بخش «الان» را شروع می‌کند."}},{"phrase":"I have ... for ... years.","meaning":{"en":"Counts your experience up to now.","tr":"Bugüne kadarki deneyimini anlatır.","fa":"تجربه‌ات را تا امروز حساب می‌کند."}},{"phrase":"I'm applying because...","meaning":{"en":"Opens the \"why\" part.","tr":"\"Neden\" kısmını başlatır.","fa":"بخش «چرا» را شروع می‌کند."}},{"phrase":"requirement","meaning":{"en":"Something an employer says you must have.","tr":"şart, aranan nitelik","fa":"شرط، چیزی که کارفرما لازم دارد"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Make it about this job","tr":"Bu işle ilgili hâle getir","fa":"معرفی‌ات را به همین کار ربط بده"},"item":"Weak: I was born in Izmir. I studied at a good university, and I am hard-working and friendly. I need a new job. Your facts: sales assistant in Izmir; about 30 phone customers a day for three years; you want to move into business sales.","answer":"I currently work as a sales assistant in Izmir. I have sold phones to about 30 customers a day for three years. I'm applying because I want to move into business sales.","walk":[{"en":"Cut the birth place and the adjectives. The ad doesn't ask for them.","tr":"Doğum yerini ve sıfatları çıkar. İlan bunları istemiyor.","fa":"محل تولد و صفت‌ها را حذف کن. آگهی این‌ها را نخواسته است."},{"en":"Add your job now and one fact with a number.","tr":"Şimdiki işini ve içinde sayı olan bir gerçeği ekle.","fa":"کار فعلی‌ات و یک واقعیت با عدد را اضافه کن."},{"en":"End with why this job. \"I need a new job\" is only about you.","tr":"\"Neden bu iş\" ile bitir. \"I need a new job\" yalnızca seninle ilgilidir.","fa":"در آخر بگو چرا همین کار را می‌خواهی. «I need a new job» فقط درباره‌ی خودت است."}]},"quick":{"prompt":"In your introduction, start with ___.","options":["what you do now","where you were born","why you dislike your job"],"correct":0,"why":{"en":"what you do now: it tells the interviewer at once why you are in the room.","tr":"what you do now: mülakatçıya neden o odada olduğunu hemen söyler.","fa":"جواب what you do now است، چون همان اول به مصاحبه‌کننده می‌گوید چرا اینجا هستی."}},"remember":{"en":"Now, before, why. If the job ad does not need a fact, leave it out. You can now plan a 60 to 90 second introduction for one real job. Next, you write and say your own.","tr":"Şimdi, önce, neden. İlanın ihtiyaç duymadığı bir bilgiyi söyleme. Artık gerçek bir iş için 60-90 saniyelik bir tanıtım planlayabilirsin. Sırada kendi tanıtımını yazmak ve söylemek var.","fa":"سه بخش را یادت باشد: الان، قبلاً، چرا. واقعیتی را که آگهی لازم ندارد نگو. حالا می‌توانی برای یک کار واقعی یک معرفی ۶۰ تا ۹۰ ثانیه‌ای آماده کنی. در ادامه معرفی خودت را می‌نویسی و بلند می‌گویی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Recent work: present perfect continuous","tr":"Son dönemdeki işin: present perfect continuous","fa":"کار این مدت: حال کامل استمراری"},"steps":[{"en":"Started before, still going on: have been + -ing.","tr":"Önce başladı, hâlâ sürüyor: have been + -ing.","fa":"وقتی کاری قبلاً شروع شده و هنوز ادامه دارد، have been و فعل با ing می‌آوری.","ex":"I have been training new staff since May."},{"en":"A result or a number: have + past participle.","tr":"Bir sonuç ya da sayı: have + üçüncü hâl.","fa":"برای نتیجه یا عدد، have و اسم مفعول می‌آوری.","ex":"I have trained four people so far."},{"en":"know, like, own: no -ing.","tr":"know, like, own: -ing almaz.","fa":"فعل‌های know، like و own شکل ing نمی‌گیرند.","ex":"I have known my manager for six years."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Still going on","I have been training new staff since May."],["Result or number","I have trained four people so far."],["Question","What have you been working on recently?"],["Stative verb: no -ing","I have known my manager for six years."]]},"body":{"en":"B2: in your introduction, add one recent activity with have been + -ing (for example 'For the last year I have been...').","tr":"B2: tanıtımına have been + -ing ile yakın zamanda yaptığın bir etkinlik ekle (örneğin 'For the last year I have been...').","fa":"در مسیر B2: در معرفی‌ات یک کار تازه را با have been و فعل با ing بگو (مثلاً «For the last year I have been...»)."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
